'use strict';

const path = require('node:path');
const { exec } = require('node:child_process');
const util = require('node:util');
const execAsync = util.promisify(exec);

const { parsePomXml, getPomPropertyValue } = require('../util/pom');
const { javaCdsMajorFor, TRACKED_MAJOR_MAP } = require('../constants');

const NODE_TRACK = Object.keys(TRACKED_MAJOR_MAP);

// Resolve a Node dep's *cds* major from its installed npm major, using the
// same mapping the consistency check applies. Identity for @sap/cds and
// @sap/cds-dk (npm major === cds major); table lookup for @sap/cds-mtxs
// (major 4 → cds 10) and @sap/cds-compiler (major 7 → cds 10).
function cdsMajorFor(name, npmMajor) {
  const map = TRACKED_MAJOR_MAP[name];
  if (map === null) return npmMajor;
  return map[npmMajor] ?? null;
}

async function verifyNode(ctx, cds) {
  const semver = require('semver');
  const mismatches = [];
  let stdout = '';
  try {
    const r = await execAsync(
      `npm ls ${NODE_TRACK.join(' ')} --depth=0 --json`,
      { cwd: cds.root, maxBuffer: 8 * 1024 * 1024 }
    );
    stdout = r.stdout;
  } catch (e) {
    stdout = e.stdout || '';   // npm ls returns non-zero for unmet peer deps; parse anyway
  }
  if (!stdout) return mismatches;

  let tree;
  try { tree = JSON.parse(stdout); } catch { return mismatches; }
  const walk = (deps) => {
    if (!deps) return;
    for (const [name, entry] of Object.entries(deps)) {
      if (NODE_TRACK.includes(name) && entry.version) {
        const npmMajor = semver.major(entry.version);
        const cdsMajor = cdsMajorFor(name, npmMajor);
        if (cdsMajor !== ctx.target) {
          mismatches.push({ scope: 'node', name, resolved: entry.version, expected: ctx.target });
        }
      }
      walk(entry.dependencies);
    }
  };
  walk(tree.dependencies);
  return mismatches;
}

function verifyJava(ctx, cds) {
  const mismatches = [];
  for (const pomPath of ctx.project.pomXmlFiles) {
    let pom;
    try { pom = parsePomXml(pomPath); } catch { continue; }
    const raw = getPomPropertyValue(pom, 'cds.services.version');
    if (!raw) continue;
    const m = raw.match(/^(\d+)/);
    if (!m) continue;
    const javaMajor = parseInt(m[1], 10);
    const cdsMajor = javaCdsMajorFor(javaMajor);
    if (cdsMajor !== ctx.target) {
      mismatches.push({
        scope: 'java', file: path.relative(cds.root, pomPath),
        name: 'cds.services.version', resolved: raw, expected: ctx.target,
      });
    }
  }
  return mismatches;
}

async function runVerify(ctx, cds) {
  const { error, bold, dim } = require('../../../lib/util/term');
  const mismatches = [
    ...(ctx.project.isNode ? await verifyNode(ctx, cds) : []),
    ...(ctx.project.isJava ? verifyJava(ctx, cds) : []),
  ];
  if (mismatches.length > 0) {
    console.log();
    console.log(bold('Verification:'));
    for (const m of mismatches) {
      const prefix = m.file ? `${m.file}  ` : '';
      console.log(`  ${error('✗')} ${prefix}${m.name} ${m.resolved}  ${dim(`(expected cds ${m.expected})`)}`);
    }
  }
  ctx.verifyMismatches = mismatches;
  return { mismatches };
}

module.exports = { runVerify, cdsMajorFor };
